-- M2.5.3: Knowledge Base & Operations pilot bundle — SOP, Onboarding Guide, Policy Document
-- Mirrors packages/shared/src/system-templates.ts (KB_OPS_SCHEMA_FIELDS + withEssentials).

insert into templates (name, description, structure_json, is_system, is_shared, slug, metadata)
