le] — [Responsibility]"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Exceptions"}]},{"type":"paragraph","content":[{"type":"text","text":"Known edge cases and what to do when the standard steps don''t apply.","marks":[{"type":"italic"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"[Situation] — [What to do instead]"}]}]}]}]}'::jsonb,
